function fichaEtapa(titulo, conceptos, o = {}) {
  return [
    h2(titulo),
    ficha([
      ["Fechas y hito", o.fechas ?? "[desde – hasta] · hito: [tag y fecha en que el JTP lo anotó]"],
      ["Qué se hizo", o.hizo ?? PEND],
      ["Cómo y con qué", o.como ?? "[herramientas, librerías, parámetros y semillas]"],
      ["Conceptos de la materia", conceptos.map((c) => "- " + c)],
      ["Resultados y evidencias", o.resultados ?? "[figuras, métricas y dónde están los archivos]"],
      ["Problemas y decisiones", o.problemas ?? "[qué falló, qué se probó y qué se decidió → sección 5]"],
    ]),
    p("", { after: 80 }),
  ];
}

